;outline:0}.side textarea{min-height:150px;resize:vertical}.side .button{width:100%;margin-top:8px}.workspace{min-width:0;display:grid;grid-template-rows:49px minmax(0,1fr) 54px}.filebar{display:flex;align-items:center;gap:8px;padding:8px 12px;border-bottom:1px solid var(--line)}.filebar input{min-width:0;flex:1;height:32px;padding:0 10px;border:1px solid var(--line);border-radius:8px;background:#0b0b0b;color:#ddd}.filebar button{height:32px;padding:0 11px;border:1px solid var(--line);border-radius:8px;background:#111;color:#bbb}.editor{width:100%;height:100%;resize:none;border:0;outline:0;padding:20px;background:#080808;color:#ddd;font:13px/1.7 ui-monospace,SFMono-Regular,Consolas,monospace}.actionbar{display:flex;align-items:center;gap:8px;padding:8px 12px;border-top:1px solid var(--line)}.actionbar .status{margin-right:auto;color:#777;font-size:12px}.notice{margin-bottom:12px;padding:15px;border:1px solid #40351b;border-radius:12px;background:#171207;color:#e1c98d}.notice[hidden],.mode[hidden]{display:none}#output{white-space:pre-wrap;color:#aaa;font:12px/1.55 ui-monospace,monospace;max-height:180px;overflow:auto}.danger{color:#ff8b8b}.error{color:#ff8585;font-size:12px}.spinner{display:inline-block;width:12px;height:12px;border:2px solid #555;border-top-color:#fff;border-radius:50%;animation:spin .7s linear infinite}@keyframes spin{to{transform:rotate(1turn)}}@media(max-width:820px){.shell{width:min(100% - 20px,1240px)}.hero{grid-template-columns:1fr;padding-top:24px}.panel{grid-template-columns:1fr}.side{border-right:0;border-bottom:1px solid var(--line)}.workspace{min-height:520px}.hero h1{font-size:46px}}</style></head><body><div class="shell"><header class="top"><div class="brand">LChat <span>/ creator</span></div><a href="../index.php">← Messenger</a></header><section class="hero"><div><h1>Create a website.<br>Just describe.</h1><p>AI will assemble the page via local Ollama or download ready-made HTML, CSS, JavaScript and safe PHP-templates.</p></div><div class="site-status"><small>Your permanent address</small><a id="public-url">chat.lbs.su/sites/<?=htmlspecialchars(strtolower($user['username']),ENT_QUOTES,'UTF-8')?>/</a></div></section><div id="permission" class="notice" hidden>To publish please confirm the request from <b>@service</b>. Send first <b>/sitecreator</b> bot <b>@compilerbot</b>, then in chat @service — <b>/allow sitecreator</b>.</div><nav class="tabs"><button class="active" data-tab="ai">Create with AI</button><button data-tab="upload">Download it yourself</button></nav><section class="panel"><aside class="side"><div id="ai-mode" class="mode"><h2>AI Creator</h2><p>Describe style, blocks and purpose. AI will create a project and immediately update your permanent website.</p><label>DESCRIPTION</label><textarea id="prompt" placeholder="For example: minimalistic game server website, black background, tariffs and FAQ"></textarea><button id="generate" class="button primary">Create with AI</button><pre id="output">Ready to generate.</pre></div><div id="upload-mode" class="mode" hidden><h2>Your files</h2><p>Up to 20 text files with a total size of 1 MiB. Needed index.html or index.php.</p><button id="pick-files" class="button">Select files</button><button id="pick-folder" class="button">Select folder</button><input id="files-input" type="file" multiple accept=".html,.htm,.css,.js,.json,.txt,.svg,.php" hidden><input id="folder-input" type="file" multiple webkitdirectory hidden><label>NAME</label><input id="site-name" maxlength="80" placeholder="My website"><p id="file-count">No files selected</p></div><div id="error" class="error"></div></aside><main class="workspace"><div class="filebar"><input id="path" value="index.html" aria-label="File path"><button id="open-file">Open</button><button id="new-file">New</button></div><textarea id="editor" class="editor" spellcheck="false"><!doctype html>
